import { defineConfig } from 'vite'
import react from '@vitejs/plugin-react'

// host: 0.0.0.0 so the dev server is reachable from the preview WebView and
// from another device on the same network.
export default defineConfig({
  plugins: [react()],
  server: { host: '0.0.0.0', port: 5173 },
})

import { useEffect, useState } from 'react'
import type { Session } from '@supabase/supabase-js'
import { supabase } from './lib/supabaseClient'
import { signInWithGitHub, signInWithGoogle, signInWithMagicLink, signOut } from './lib/auth'
import './App.css'

type Note = {
  id: number
  title: string
  body: string
  created_at: string
}

export default function App() {
  const [session, setSession] = useState<Session | null>(null)
  const [email, setEmail] = useState('')
  const [status, setStatus] = useState('')
  const [notes, setNotes] = useState<Note[]>([])
  const [title, setTitle] = useState('')

  useEffect(() => {
    supabase.auth.getSession().then(({ data }) => setSession(data.session))
    const { data } = supabase.auth.onAuthStateChange((_event, next) => setSession(next))
    return () => data.subscription.unsubscribe()
  }, [])

  useEffect(() => {
    if (!session) return
    supabase
      .from('notes')
      .select('id, title, body, created_at')
      .order('created_at', { ascending: false })
      .then(({ data, error }) => {
        if (error) setStatus(error.message)
        else setNotes((data ?? []) as Note[])
      })
  }, [session])

  async function addNote() {
    if (!title.trim()) return
    const { error } = await supabase.from('notes').insert({ title: title.trim() })
    if (error) {
      setStatus(error.message)
      return
    }
    setTitle('')
    const { data } = await supabase
      .from('notes')
      .select('id, title, body, created_at')
      .order('created_at', { ascending: false })
    setNotes((data ?? []) as Note[])
  }

  if (!session) {
    return (
      <main className="card">
        <h1>{{projectName}}</h1>
        <p className="muted">Sign in to reach your Supabase project.</p>
        <button onClick={() => signInWithGitHub()}>Continue with GitHub</button>
        <button onClick={() => signInWithGoogle()}>Continue with Google</button>
        <div className="row">
          <input
            value={email}
            onChange={(event) => setEmail(event.target.value)}
            placeholder="you@example.com"
            inputMode="email"
          />
          <button onClick={() => signInWithMagicLink(email).then(() => setStatus('Check your inbox.'))}>
            Magic link
          </button>
        </div>
        {status && <p className="muted">{status}</p>}
      </main>
    )
  }

  return (
    <main className="card">
      <header className="row">
        <h1>Notes</h1>
        <button onClick={() => signOut()}>Sign out</button>
      </header>
      <p className="muted">{session.user.email}</p>
      <div className="row">
        <input value={title} onChange={(event) => setTitle(event.target.value)} placeholder="New note" />
        <button onClick={addNote}>Add</button>
      </div>
      <ul>
        {notes.map((note) => (
          <li key={note.id}>
            <strong>{note.title}</strong>
            <span className="muted">{new Date(note.created_at).toLocaleString()}</span>
          </li>
        ))}
      </ul>
      {status && <p className="muted">{status}</p>}
    </main>
  )
}

:root {
  color-scheme: dark;
  font-family: system-ui, -apple-system, 'Segoe UI', sans-serif;
}

body {
  margin: 0;
  min-height: 100vh;
  display: grid;
  place-items: center;
  background: #0d1117;
  color: #c9d1d9;
}

.card {
  width: min(520px, 92vw);
  padding: 24px;
  border-radius: 12px;
  background: #161b22;
  border: 1px solid #30363d;
  display: grid;
  gap: 12px;
}

.row {
  display: flex;
  gap: 8px;
  align-items: center;
}

.row input {
  flex: 1;
}

input,
button {
  font: inherit;
  padding: 10px 12px;
  border-radius: 8px;
  border: 1px solid #30363d;
  background: #0d1117;
  color: inherit;
}

button {
  background: #238636;
  border-color: #2ea043;
  cursor: pointer;
}

ul {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 8px;
}

li {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  padding: 10px;
  border-radius: 8px;
  background: #0d1117;
}

.muted {
  color: #8b949e;
  font-size: 13px;
}

/// <reference types="vite/client" />

interface ImportMetaEnv {
  readonly VITE_SUPABASE_URL?: string
  readonly VITE_SUPABASE_ANON_KEY?: string
}

interface ImportMeta {
  readonly env: ImportMetaEnv
}

import { createClient } from '@supabase/supabase-js'

// Vite only exposes variables prefixed with VITE_, and only to client code.
// The anon key is safe here: row level security is what protects the data.
const url = import.meta.env.VITE_SUPABASE_URL as string | undefined
const anonKey = import.meta.env.VITE_SUPABASE_ANON_KEY as string | undefined

if (!url || !anonKey) {
  console.warn('Set VITE_SUPABASE_URL and VITE_SUPABASE_ANON_KEY before signing in.')
}

export const supabase = createClient(
  url ?? 'http://127.0.0.1:54321',
  anonKey ?? 'public-anon-key',
  { auth: { persistSession: true, detectSessionInUrl: true } },
)

import { supabase } from './supabaseClient'

export function signInWithGitHub() {
  return supabase.auth.signInWithOAuth({
    provider: 'github',
    options: { redirectTo: window.location.origin },
  })
}

export function signInWithGoogle() {
  return supabase.auth.signInWithOAuth({
    provider: 'google',
    options: { redirectTo: window.location.origin },
  })
}

export function signInWithMagicLink(email: string) {
  return supabase.auth.signInWithOtp({
    email,
    options: { emailRedirectTo: window.location.origin },
  })
}

export function signOut() {
  return supabase.auth.signOut()
}

-- Run this in the Supabase SQL editor (Database -> SQL editor).
create table if not exists public.notes (
  id bigserial primary key,
  user_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
  title text not null,
  body text not null default '',
  created_at timestamptz not null default now()
);

alter table public.notes enable row level security;

create policy "read own notes" on public.notes
  for select using (auth.uid() = user_id);

create policy "write own notes" on public.notes
  for insert with check (auth.uid() = user_id);

create policy "update own notes" on public.notes
  for update using (auth.uid() = user_id);

create policy "delete own notes" on public.notes
  for delete using (auth.uid() = user_id);
